package support

import "embed"

// Generated by tools/supportart, shared with the checkout. Birds register
// these in their own application emoji library, with their normal hashing
// and upload rules. No runtime dependency on a website or another bot.
//
//go:embed icons/*.png
var iconArt embed.FS

// IconPNG returns a named mark, or false for an unknown key. The network
// names ethereum, solana and monero reuse their native coin's mark.
func IconPNG(key string) ([]byte, bool) {
	switch key {
	case "ethereum":
		key = IconETH
	case "solana":
		key = IconSOL
	case "monero":
		key = IconXMR
	}
	for _, known := range Icons {
		if key == known {
			png, err := iconArt.ReadFile("icons/" + key + ".png")
			return png, err == nil
		}
	}
	return nil, false
}
